/// The same where the embedder is itself WebAssembly. There a typed function
/// brings a wrapper of its own into the embedder's module, a few kilobytes for
/// each import. So one function serves them all, told which import it is by
/// that import's place in `IMPORTS`.
///
/// All but the imports where the system reaches the program: what ends a
/// program there is the runtime's own error, which has to arrive as what it
/// is, and the one function for all reports a failure as its text.
#[cfg(target_arch = "wasm32")]
pub(crate) fn register(store: &mut impl AsStoreMut, env: &FunctionEnv<GuiEnv>, exports: &mut Exports) {
    use super::ValType;
    let wasm = |types: &[ValType]| -> Vec<wasmer::Type> {
        types
            .iter()
            .map(|ty| match ty {
                ValType::I32 => wasmer::Type::I32,
                ValType::I64 => wasmer::Type::I64,
                ValType::F32 => wasmer::Type::F32,
                ValType::F64 => wasmer::Type::F64,
            })
            .collect()
    };
    for (index, sig) in super::IMPORTS.iter().enumerate() {
        if matches!(sig.name, "wguiInstancePollEvents" | "wguiInstanceWaitEvents") {
            continue;
        }
        let ty = wasmer::FunctionType::new(wasm(sig.params), wasm(sig.results));
        let function = Function::new_with_env(store, env, ty, move |env, args| call(index, env, args));
        exports.insert(sig.name, function);
    }
    exports.insert("wguiInstancePollEvents", Function::new_typed_with_env(store, env, import_instance_poll_events));
    exports.insert("wguiInstanceWaitEvents", Function::new_typed_with_env(store, env, import_instance_wait_events));
}

#[cfg(target_arch = "wasm32")]
fn call(index: usize, env: FunctionEnvMut<'_, GuiEnv>, args: &[wasmer::Value]) -> Result<Vec<wasmer::Value>, RuntimeError> {
    use wasmer::Value;
    // The engine checked the arguments against the import's type. Here they
    // are taken apart once, as bits, for whichever import this is.
    let mut raw = [0_u64; 7];
    for (bits, value) in raw.iter_mut().zip(args) {
        *bits = match value {
            Value::I32(value) => u64::from(*value as u32),
            Value::I64(value) => *value as u64,
            Value::F64(value) => value.to_bits(),
            _ => 0,
        };
    }
    let value = |result: Result<u32, RuntimeError>| result.map(|value| vec![Value::I32(value as i32)]);
    let nothing = |result: Result<(), RuntimeError>| result.map(|()| Vec::new());
    match index {
        0 => value(import_get_version(env)),
        1 => value(import_has_feature(env, raw[0] as u32)),
        2 => value(import_get_features(env, raw[0] as u32, raw[1] as u32, raw[2] as u32)),
        3 => value(import_create_instance(env, raw[0] as u32, raw[1] as u32)),
        4 => nothing(import_instance_destroy(env, raw[0] as u32)),
        5 => value(import_instance_get_info(env, raw[0] as u32, raw[1] as u32)),
        6 => value(import_instance_poll_events(env, raw[0] as u32, raw[1] as u32, raw[2] as u32, raw[3] as u32)),
        7 => value(import_instance_wait_events(env, raw[0] as u32, raw[1], raw[2] as u32)),
        8 => value(import_instance_wake(env, raw[0] as u32)),
        9 => value(import_instance_set_event_mask(env, raw[0] as u32, raw[1])),
        10 => value(import_instance_get_time(env, raw[0] as u32, raw[1] as u32)),
        11 => value(import_instance_get_displays(env, raw[0] as u32, raw[1] as u32, raw[2] as u32, raw[3] as u32)),
        12 => value(import_instance_create_window(env, raw[0] as u32, raw[1] as u32, raw[2] as u32)),
        13 => value(import_instance_create_cursor(env, raw[0] as u32, raw[1] as u32, raw[2] as u32)),
        14 => value(import_instance_get_clipboard_info(env, raw[0] as u32, raw[1] as u32, raw[2] as u32)),
        15 => value(import_instance_read_clipboard(env, raw[0] as u32, raw[1] as u32, raw[2] as u32, raw[3] as u32, raw[4] as u32, raw[5] as u32, raw[6] as u32)),
        16 => value(import_instance_request_clipboard(env, raw[0] as u32, raw[1] as u32, raw[2] as u32, raw[3] as u32, raw[4])),
        17 => value(import_instance_write_clipboard(env, raw[0] as u32, raw[1] as u32, raw[2] as u32, raw[3] as u32, raw[4])),
        18 => value(import_display_get_info(env, raw[0] as u32, raw[1] as u32)),
        19 => value(import_display_get_name(env, raw[0] as u32, raw[1] as u32, raw[2] as u32, raw[3] as u32)),
        20 => nothing(import_window_destroy(env, raw[0] as u32)),
        21 => value(import_window_get_state(env, raw[0] as u32, raw[1] as u32)),
        22 => value(import_window_get_surface_selector(env, raw[0] as u32, raw[1] as u32, raw[2] as u32, raw[3] as u32)),
        23 => value(import_window_set_title(env, raw[0] as u32, raw[1] as u32, raw[2] as u32)),
        24 => value(import_window_set_size(env, raw[0] as u32, raw[1] as u32, raw[2] as u32)),
        25 => value(import_window_set_size_limits(env, raw[0] as u32, raw[1] as u32, raw[2] as u32, raw[3] as u32, raw[4] as u32)),
        26 => value(import_window_set_position(env, raw[0] as u32, raw[1] as u32 as i32, raw[2] as u32 as i32)),
        27 => value(import_window_set_flags(env, raw[0] as u32, raw[1], raw[2], raw[3] as u32)),
        28 => value(import_window_set_fullscreen(env, raw[0] as u32, raw[1] as u32, raw[2])),
        29 => value(import_window_focus(env, raw[0] as u32)),
        30 => value(import_window_request_attention(env, raw[0] as u32, raw[1] as u32)),
        31 => value(import_window_request_redraw(env, raw[0] as u32)),
        32 => value(import_window_set_cursor_shape(env, raw[0] as u32, raw[1] as u32)),
        33 => value(import_window_set_custom_cursor(env, raw[0] as u32, raw[1] as u32)),
        34 => value(import_window_set_cursor_visible(env, raw[0] as u32, raw[1] as u32)),
        35 => value(import_window_set_cursor_grab(env, raw[0] as u32, raw[1] as u32, raw[2])),
        36 => value(import_window_set_cursor_position(env, raw[0] as u32, f64::from_bits(raw[1]), f64::from_bits(raw[2]))),
        37 => value(import_window_set_text_input(env, raw[0] as u32, raw[1] as u32)),
        38 => value(import_window_reset_text_input(env, raw[0] as u32)),
        39 => value(import_window_set_default_actions(env, raw[0] as u32, raw[1] as u32)),
        40 => value(import_window_present_pixels(env, raw[0] as u32, raw[1] as u32, raw[2] as u32, raw[3] as u32)),
        41 => nothing(import_cursor_destroy(env, raw[0] as u32)),
        _ => Err(RuntimeError::new("no such import")),
    }
}
